mapper.select:
SELECT od.ORDER_DETAIL_ID AS orderDetailId, o.VENDOR_NAME AS vendorName, o.VENDOR_CODE AS vendorCode, o.EXT_PURCHASER_ORG_CODE AS extPurchaserOrgCode, o.EXT_PURCHASER_ORG_NAME AS extPurchaserOrgName, o.CEEA_ORG_CODE AS ceeaOrgCode, o.CEEA_ORG_NAME AS ceeaOrgName, od.EXT_USE_DEPARTMENT_CODE AS extUseDepartmentCode, od.EXT_USE_DEPARTMENT_NAME AS extUseDepartmentName, od.MATERIAL_CODE AS materialCode, od.MATERIAL_NAME AS materialName, od.SPECIFICATION AS specification, o.EXT_APPLY_DATE AS extApplyDate, o.CEEA_PURCHASE_ORDER_DATE AS ceeaPurchaseOrderDate, o.ORDER_NUMBER AS orderNumber, n.DELIVERY_NUMBER AS deliveryNumber, od.DELIVERY_DATE AS deliveryDate, od.EXT_DELIVERY_CYCLE AS extDeliveryCycle, od.UNIT AS unit, od.EXT_BRAND AS extBrand, o.CEEA_EMP_NO AS ceeaEmpNo, o.CEEA_EMP_USER_ID AS ceeaEmpUseId, o.CEEA_EMP_USERNAME AS ceeaEmpUsername, od.REQUIREMENT_QUANTITY AS requirementQuantity, od.ORDER_NUM AS orderNum, od.STORAGE_NUM AS storageNum, od.RECEIVE_NUM AS receiveNum, od.RECEIVE_SUM AS receiveSum, od.EXT_DETAIL_STATUS AS orderDetailStatus, nd.EXT_DETAIL_STATUS AS deliveryNoteDetailStatus, od.CLOSED_CAUSE AS orderCancelReason,
o.EXT_VENDOR_CONTACTS, o.EXT_VENDOR_PHONE, o.CEEA_PURCHASE_TYPE, od.EXT_USER_NAME, od.EXT_USER_CODE, nd.EXT_STORAGE_TIME, od.CATEGORY_NAME, nd.EXT_RECEIVE_TIME,
coalesce ( GREATEST(nd.EXT_STORAGE_TIME , nd.EXT_RECEIVE_TIME), nd.EXT_RECEIVE_TIME, nd.EXT_STORAGE_TIME ) AS easReceiveTime,
rl.EXT_BUY_TYPE FROM scc_sc_order_detail od JOIN scc_sc_order o ON od.ORDER_ID = o.ORDER_ID and o.ORDER_STATUS not in ('REFUSED', 'REFUSED') left join scc_pr_requirement_line rl on rl.REQUIREMENT_LINE_ID= od.CEEA_REQUIREMENT_LINE_ID LEFT JOIN ( SELECT nd.* FROM scc_sc_delivery_note_detail nd JOIN ( SELECT DELIVERY_NOTE_DETAIL_ID FROM ( SELECT COALESCE ( GREATEST( nd.EXT_STORAGE_TIME, nd.EXT_RECEIVE_TIME ), nd.EXT_RECEIVE_TIME, nd.EXT_STORAGE_TIME ) AS easReceiveTime, ORDER_DETAIL_ID, DELIVERY_NOTE_DETAIL_ID FROM scc_sc_delivery_note_detail nd ORDER BY easReceiveTime DESC ) temp GROUP BY ORDER_DETAIL_ID ) t ON t.DELIVERY_NOTE_DETAIL_ID = nd.DELIVERY_NOTE_DETAIL_ID ) nd ON nd.ORDER_DETAIL_ID = od.ORDER_DETAIL_ID
LEFT JOIN scc_sc_delivery_note n ON n.DELIVERY_NOTE_ID = nd.DELIVERY_NOTE_ID WHERE 1=1
AND o.CEEA_PURCHASE_ORDER_DATE < #{ceeaPurchaseOrderDate[1]} AND o.CEEA_PURCHASE_ORDER_DATE >= #{ceeaPurchaseOrderDate[0]}
AND o.CEEA_EMP_USERNAME LIKE CONCAT('%',#{ceeaEmpUsername},'%')
AND o.VENDOR_NAME LIKE CONCAT('%',#{vendorName},'%')
AND o.VENDOR_CODE = #{vendorCode}
AND o.CEEA_ORG_CODE = #{ceeaOrgCode}
AND o.CEEA_ORG_ID = #{ceeaOrgId}
AND o.CEEA_EMP_NO = #{ceeaEmpNo}
AND o.ORDER_NUMBER LIKE CONCAT('%',#{orderNumber},'%')
AND od.MATERIAL_CODE LIKE CONCAT('%',#{materialCode},'%')
AND od.DELIVERY_DATE < #{deliveryDate[1]} AND od.DELIVERY_DATE >= #{deliveryDate[0]}
